import{_ as t,o as s,c as r,ah as o}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Direction","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/direction/index.md","filePath":"src/en/guide/direction/index.md"}'),a={name:"en/guide/direction/index.md"};function i(n,e,d,h,c,p){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="direction" tabindex="-1">Direction <a class="header-anchor" href="#direction" aria-label="Permalink to &quot;Direction&quot;">​</a></h1><p>Two profiles are meant for the people who run the school without doing its day-to-day data entry:</p><ul><li>the <strong>site director</strong> — the head of a campus. They are attached to one or more sites and decide what concerns them;</li><li>the <strong>general director</strong> — the head of the school or its founder. They see every site and may decide everything.</li></ul><p>These profiles are part of the <strong>Pilotage</strong> module. The administrator assigns them, from <a href="/era-guide/en/guide/admin/personnel-utilisateurs.html">Staff and user accounts</a>.</p><div class="info custom-block"><p class="custom-block-title">What the direction does not see</p><p>A director has no access to the operational screens: cash desk, grades, application files, settings. They see the requests waiting for their decision, gathered in <a href="/era-guide/en/guide/direction/a-approuver.html">To approve</a>, and the <a href="/era-guide/en/guide/direction/pilotage.html">Pilotage</a> page with their sites&#39; indicators.</p></div><h2 id="your-space" tabindex="-1">Your space <a class="header-anchor" href="#your-space" aria-label="Permalink to &quot;Your space&quot;">​</a></h2><p>When you sign in, the <strong>Dashboard</strong> lists what is waiting for your decision, with the number of pending requests. The <strong>Direction</strong> space of the menu opens on <a href="/era-guide/en/guide/direction/a-approuver.html">To approve</a>, one page with everything you may decide, followed by the <strong>Pilotage</strong> page and the three full queues:</p><ul><li><strong>Inter-site transfers</strong> — students moving between two sites;</li><li><strong>Staff transfers</strong> — an employee changing site;</li><li><strong>Expenses</strong> — the sites&#39; expense requests.</li></ul><p>A site director only sees the requests touching <strong>their</strong> sites. The general director sees everything.</p><h2 id="who-decides-what" tabindex="-1">Who decides what <a class="header-anchor" href="#who-decides-what" aria-label="Permalink to &quot;Who decides what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Request</th><th>Site director</th><th>General director</th></tr></thead><tbody><tr><td>Student transfer</td><td>approves their site&#39;s side (leaving or arriving)</td><td>may approve both</td></tr><tr><td>Staff transfer</td><td>decides when either site is theirs</td><td>decides</td></tr><tr><td>Expense</td><td>decides up to the school&#39;s <strong>threshold</strong>, included</td><td>decides, no limit</td></tr></tbody></table><p>The administrator can always decide everything.</p><p>A site <strong>without a director</strong> works as before: the secretariat approves its side of student transfers, and the administration decides staff transfers and expenses. The same goes when the director&#39;s account is deactivated.</p><h2 id="student-transfers" tabindex="-1">Student transfers <a class="header-anchor" href="#student-transfers" aria-label="Permalink to &quot;Student transfers&quot;">​</a></h2><p>A transfer must be approved by the site the student leaves <strong>and</strong> the site they join. Open the request with <strong>Review</strong>:</p><ul><li>your site&#39;s block offers <strong>Approve origin</strong> or <strong>Approve destination</strong>; for the destination, choose the receiving class;</li><li>the other site&#39;s block reads <strong>Waiting for this site&#39;s approval</strong> until it has answered.</li></ul><p>The transfer runs as soon as both sides are approved, in any order. You can also <strong>Reject</strong> the request, with a reason.</p><h2 id="staff-transfers" tabindex="-1">Staff transfers <a class="header-anchor" href="#staff-transfers" aria-label="Permalink to &quot;Staff transfers&quot;">​</a></h2><p>One decision is enough: <strong>Approve</strong> applies the change of site, <strong>Reject</strong> asks for a reason. Both sites&#39; directions are told; the first one to decide closes the request.</p><h2 id="expenses" tabindex="-1">Expenses <a class="header-anchor" href="#expenses" aria-label="Permalink to &quot;Expenses&quot;">​</a></h2><p>Open an expense to see its amount, description and supporting document, then <strong>Approve</strong> or <strong>Reject</strong>.</p><p>Above the threshold, the page says so — <em>Amount above the site direction&#39;s approval threshold</em> — and the decision goes to the general direction or an administrator. You are then not notified of those expenses, but you see them in your sites&#39; list.</p><p>The administrator sets this threshold in <a href="/era-guide/en/guide/admin/parametres-application.html#approvals">Application settings → Approvals</a>.</p><h2 id="classes-over-capacity" tabindex="-1">Classes over capacity <a class="header-anchor" href="#classes-over-capacity" aria-label="Permalink to &quot;Classes over capacity&quot;">​</a></h2><p>When a class of your site takes a student while it is already full, you receive a <em>Class over capacity</em> notification: who forced the assignment, the headcount reached and the <strong>reason</strong> given. There is nothing to approve: it is information, so these overrides no longer go unnoticed.</p><h2 id="getting-requests-on-your-phone" tabindex="-1">Getting requests on your phone <a class="header-anchor" href="#getting-requests-on-your-phone" aria-label="Permalink to &quot;Getting requests on your phone&quot;">​</a></h2><p>In <strong>Settings → Notifications</strong>, turn on notifications on your phone. Each new request then arrives as a notification; tapping it opens the <a href="/era-guide/en/guide/direction/a-approuver.html">To approve</a> page, with that request brought forward.</p>',27)])])}const g=t(a,[["render",i]]);export{u as __pageData,g as default};
